import React, { useState, useEffect, useRef } from 'react';
import { motion } from 'framer-motion';
import { Link } from 'react-router-dom';
import { 
  Package, 
  Truck, 
  Search, 
  CheckCircle, 
  Clock, 
  MapPin, 
  Phone, 
  AlertCircle,
  Cloud,
  Navigation,
  Calendar,
  Map,
  Route,
  Settings,
  AlertTriangle
} from 'lucide-react';
import * as L from 'leaflet';
import 'leaflet/dist/leaflet.css';

interface OrderStatus {
  id: string;
  status: string;
  estimatedDelivery: string;
  items: { name: string; quantity: number }[];
  currentLocation: string;
  lastUpdate: string;
  trackingNumber: string;
  customerName: string;
  deliveryAddress: string;
  priority: string;
  assignedEmployee?: {
    id: string;
    name: string;
    phone: string;
    currentLocation?: { lat: number; lng: number };
  };
  coordinates: { lat: number; lng: number };
}

const CustomerPortal = () => {
  const [orderId, setOrderId] = useState('');
  const [orderStatus, setOrderStatus] = useState<OrderStatus | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const mapRef = useRef<HTMLDivElement>(null);
  const mapInstanceRef = useRef<L.Map | null>(null);

  // Mock order data
  const mockOrders = {
    'ORD12345': {
      id: 'ORD12345',
      status: 'shipped',
      estimatedDelivery: '2024-05-01',
      items: [{ name: 'Premium Package', quantity: 2 }],
      currentLocation: 'Distribution Center, Delhi',
      lastUpdate: '2024-04-26 10:30 AM',
      trackingNumber: 'TRK-78945612',
      customerName: 'Rahul Sharma',
      deliveryAddress: '123 Main Street, Delhi, 110001',
      priority: 'express',
      assignedEmployee: {
        id: 'EMP001',
        name: 'Rajesh Kumar',
        phone: '+91-98765-43210',
        currentLocation: { lat: 28.6139, lng: 77.2090 }
      },
      coordinates: { lat: 28.6139, lng: 77.2090 }
    },
    'ORD67890': {
      id: 'ORD67890',
      status: 'delivered',
      estimatedDelivery: '2024-04-20',
      items: [{ name: 'Standard Package', quantity: 1 }],
      currentLocation: 'Delivered',
      lastUpdate: '2024-04-20 02:15 PM',
      trackingNumber: 'TRK-45678901',
      customerName: 'Priya Patel',
      deliveryAddress: '456 Park Avenue, Mumbai, 400001',
      priority: 'standard',
      coordinates: { lat: 19.0760, lng: 72.8777 }
    },
    'ORD11223': {
      id: 'ORD11223',
      status: 'processing',
      estimatedDelivery: '2024-04-28',
      items: [{ name: 'Premium Package', quantity: 1 }],
      currentLocation: 'Processing Center',
      lastUpdate: '2024-04-26 09:15 AM',
      trackingNumber: 'TRK-34511223',
      customerName: 'Amit Kumar',
      deliveryAddress: '789 Business Hub, Bangalore, 560001',
      priority: 'premium',
      coordinates: { lat: 12.9716, lng: 77.5946 }
    }
  };

  const handleTrackOrder = async () => {
    if (!orderId.trim()) {
      setError('Please enter an order ID');
      return;
    }

    setLoading(true);
    setError(null);
    
    // Simulate API call
    setTimeout(() => {
      const foundOrder = mockOrders[orderId.toUpperCase()];
      
      if (foundOrder) {
        setOrderStatus(foundOrder);
        // Initialize map after a short delay
        setTimeout(() => {
          initializeMap();
        }, 100);
      } else {
        setError('Order not found. Please check your order ID and try again.');
      }
      setLoading(false);
    }, 1500);
  };

  // Initialize map
  const initializeMap = () => {
    if (!orderStatus || !mapRef.current) return;

    // Clear existing map
    if (mapInstanceRef.current) {
      mapInstanceRef.current.remove();
      mapInstanceRef.current = null;
    }

    const container = mapRef.current;
    container.style.height = '400px';
    container.style.width = '100%';

    // Initialize Leaflet map
    const map = L.map(container).setView([orderStatus.coordinates.lat, orderStatus.coordinates.lng], 13);

    // Add map tiles
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      maxZoom: 19,
      attribution: '© OpenStreetMap contributors'
    }).addTo(map);

    // Create custom icons
    const deliveryIcon = L.divIcon({
      html: '<div style="background: #10b981; color: white; border-radius: 50%; width: 30px; height: 30px; display: flex; align-items: center; justify-content: center; font-size: 16px; font-weight: bold;">📍</div>',
      iconSize: [30, 30],
      className: 'custom-div-icon'
    });

    const driverIcon = L.divIcon({
      html: '<div style="background: #3b82f6; color: white; border-radius: 50%; width: 30px; height: 30px; display: flex; align-items: center; justify-content: center; font-size: 16px; font-weight: bold;">🚚</div>',
      iconSize: [30, 30],
      className: 'custom-div-icon'
    });

    // Add delivery marker
    L.marker([orderStatus.coordinates.lat, orderStatus.coordinates.lng], { icon: deliveryIcon })
      .addTo(map)
      .bindPopup(`<b>Delivery Location</b><br>${orderStatus.deliveryAddress}`);

    // Add driver and route if available
    if (orderStatus.assignedEmployee?.currentLocation) {
      const driverLoc = orderStatus.assignedEmployee.currentLocation;
      
      // Add driver marker
      L.marker([driverLoc.lat, driverLoc.lng], { icon: driverIcon })
        .addTo(map)
        .bindPopup(`<b>Driver: ${orderStatus.assignedEmployee.name}</b><br>📱 ${orderStatus.assignedEmployee.phone}`);

      // Create route
      const routePoints = [
        [driverLoc.lat, driverLoc.lng],
        [driverLoc.lat + 0.01, driverLoc.lng + 0.01],
        [orderStatus.coordinates.lat - 0.01, orderStatus.coordinates.lng - 0.01],
        [orderStatus.coordinates.lat, orderStatus.coordinates.lng]
      ];
      
      // Add route line
      L.polyline(routePoints, {
        color: '#3b82f6',
        weight: 5,
        opacity: 0.8,
        smoothFactor: 1
      }).addTo(map);

      // Fit map to show route
      const bounds = L.latLngBounds(routePoints);
      map.fitBounds(bounds, { padding: [50, 50] });
    }

    mapInstanceRef.current = map;
  };

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 to-indigo-100">
      {/* Header */}
      <div className="bg-white shadow-md">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex items-center justify-between h-16">
            <div className="flex items-center">
              <Truck className="w-8 h-8 text-blue-600 mr-3" />
              <span className="text-xl font-bold text-gray-900">Customer Portal</span>
            </div>
            <nav className="flex space-x-8">
              <Link to="/" className="text-gray-700 hover:text-blue-600 font-medium">Home</Link>
              <Link to="/customer" className="text-blue-600 font-medium">Customer Portal</Link>
              <Link to="/employee" className="text-gray-700 hover:text-blue-600 font-medium">Employee Portal</Link>
            </nav>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
        <div className="bg-white rounded-lg shadow-xl p-8">
          <h1 className="text-3xl font-bold text-center mb-8">Track Your Order</h1>
          
          {/* Search Form */}
          <div className="max-w-md mx-auto mb-8">
            <div className="flex gap-4">
              <input
                type="text"
                placeholder="Enter Order ID (e.g., ORD12345)"
                value={orderId}
                onChange={(e) => setOrderId(e.target.value)}
                onKeyPress={(e) => e.key === 'Enter' && handleTrackOrder()}
                className="flex-1 px-4 py-2 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500"
              />
              <button
                onClick={handleTrackOrder}
                disabled={loading}
                className="px-6 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 disabled:opacity-50"
              >
                {loading ? 'Tracking...' : 'Track Order'}
              </button>
            </div>

            {error && (
              <div className="mt-4 p-3 bg-red-100 border border-red-400 text-red-700 rounded-lg">
                {error}
              </div>
            )}

            <div className="mt-4 text-sm text-gray-600">
              <p>Try these sample order IDs:</p>
              <div className="flex gap-2">
                {['ORD12345', 'ORD67890', 'ORD11223'].map((id) => (
                  <button
                    key={id}
                    onClick={() => setOrderId(id)}
                    className="px-3 py-1 bg-blue-100 text-blue-700 rounded hover:bg-blue-200 text-sm"
                  >
                    {id}
                  </button>
                ))}
              </div>
            </div>
          </div>

          {/* Order Results */}
          {orderStatus && (
            <div className="space-y-6">
              {/* Order Info */}
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                <div>
                  <h3 className="text-lg font-semibold mb-4">Order Information</h3>
                  <div className="space-y-2">
                    <div className="flex justify-between p-3 bg-gray-50 rounded">
                      <span className="text-gray-600">Order ID:</span>
                      <span className="font-medium">{orderStatus.id}</span>
                    </div>
                    <div className="flex justify-between p-3 bg-gray-50 rounded">
                      <span className="text-gray-600">Status:</span>
                      <span className={`px-2 py-1 rounded text-xs font-semibold ${
                        orderStatus.status === 'delivered' ? 'bg-green-100 text-green-700' :
                        orderStatus.status === 'shipped' ? 'bg-blue-100 text-blue-700' :
                        orderStatus.status === 'processing' ? 'bg-yellow-100 text-yellow-700' :
                        'bg-gray-100 text-gray-700'
                      }`}>
                        {orderStatus.status.charAt(0).toUpperCase() + orderStatus.status.slice(1)}
                      </span>
                    </div>
                    <div className="flex justify-between p-3 bg-gray-50 rounded">
                      <span className="text-gray-600">Customer:</span>
                      <span className="font-medium">{orderStatus.customerName}</span>
                    </div>
                    <div className="flex justify-between p-3 bg-gray-50 rounded">
                      <span className="text-gray-600">Address:</span>
                      <span className="font-medium text-sm">{orderStatus.deliveryAddress}</span>
                    </div>
                  </div>
                </div>

                <div>
                  <h3 className="text-lg font-semibold mb-4">Delivery Details</h3>
                  <div className="space-y-2">
                    <div className="flex justify-between p-3 bg-gray-50 rounded">
                      <span className="text-gray-600">Est. Delivery:</span>
                      <span className="font-medium">{orderStatus.estimatedDelivery}</span>
                    </div>
                    <div className="flex justify-between p-3 bg-gray-50 rounded">
                      <span className="text-gray-600">Tracking #:</span>
                      <span className="font-medium">{orderStatus.trackingNumber}</span>
                    </div>
                    <div className="flex justify-between p-3 bg-gray-50 rounded">
                      <span className="text-gray-600">Current Location:</span>
                      <span className="font-medium">{orderStatus.currentLocation}</span>
                    </div>
                    <div className="flex justify-between p-3 bg-gray-50 rounded">
                      <span className="text-gray-600">Last Update:</span>
                      <span className="font-medium">{orderStatus.lastUpdate}</span>
                    </div>
                  </div>
                </div>
              </div>

              {/* Map Section */}
              <div>
                <h3 className="text-lg font-semibold mb-4">Live Tracking</h3>
                <div className="bg-gray-100 rounded-lg p-4">
                  <div ref={mapRef} className="rounded-lg"></div>
                </div>
              </div>

              {/* Items */}
              <div>
                <h3 className="text-lg font-semibold mb-4">Order Items</h3>
                <div className="space-y-2">
                  {orderStatus.items.map((item, index) => (
                    <div key={index} className="flex justify-between items-center p-3 bg-gray-50 rounded">
                      <span className="font-medium">{item.name}</span>
                      <span className="px-3 py-1 bg-blue-100 text-blue-700 rounded-full text-sm">
                        Qty: {item.quantity}
                      </span>
                    </div>
                  ))}
                </div>
              </div>

              {/* Assigned Employee */}
              {orderStatus.assignedEmployee && (
                <div>
                  <h3 className="text-lg font-semibold mb-4">Delivery Agent</h3>
                  <div className="bg-blue-50 rounded-lg p-4">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                      <div>
                        <span className="text-sm text-gray-600">Name:</span>
                        <p className="font-medium">{orderStatus.assignedEmployee.name}</p>
                      </div>
                      <div>
                        <span className="text-sm text-gray-600">Phone:</span>
                        <p className="font-medium">{orderStatus.assignedEmployee.phone}</p>
                      </div>
                      <div>
                        <span className="text-sm text-gray-600">ID:</span>
                        <p className="font-medium">{orderStatus.assignedEmployee.id}</p>
                      </div>
                    </div>
                  </div>
                </div>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default CustomerPortal;
